package planparserv2

import (
	"fmt"
	"math/rand"
	"testing"

	"github.com/antlr4-go/antlr/v4"

	gen "github.com/milvus-io/milvus/internal/parser/planparserv2/generated"
)

// The expression parser is generated by galop (see generate.sh), which builds
// ANTLR's own contexts, so the visitor is unchanged. These tests check it
// against ANTLR's generated parser in LL mode, the parse handleInternal did
// before: the same trees, and the same errors to the error listeners.

// galopLexParse parses expr as handleInternal does.
func galopLexParse(expr string) (gen.IExprContext, error) {
	listener := &errorListenerImpl{}
	lexer := gen.NewPlanGalopLexer(antlr.NewInputStream(convertHanToASCII(expr)))
	lexer.RemoveErrorListeners()
	lexer.AddErrorListener(listener)
	parser := gen.NewPlanGalopParser(antlr.NewCommonTokenStream(lexer, antlr.TokenDefaultChannel))
	parser.RemoveErrorListeners()
	parser.AddErrorListener(listener)
	ast := parser.Expr()
	if err := listener.Error(); err != nil {
		return ast, err
	}
	if parser.GetCurrentToken().GetTokenType() != antlr.TokenEOF {
		return ast, errTrailingTokens
	}
	return ast, nil
}

func TestGalopParserBuildsANTLRTrees(t *testing.T) {
	names := gen.NewPlanParser(nil)
	for _, expr := range corpusList() {
		want, wantErr := benchLexParseLL(expr)
		got, gotErr := galopLexParse(expr)
		if (wantErr == nil) != (gotErr == nil) {
			t.Errorf("%q: ANTLR error %v, galop error %v", expr, wantErr, gotErr)
			continue
		}
		if wantErr == nil && want.ToStringTree(nil, names) != got.ToStringTree(nil, names) {
			t.Errorf("%q: different trees:\n ANTLR %s\n galop %s", expr, want.ToStringTree(nil, names), got.ToStringTree(nil, names))
		}
	}
}

// allErrors records every error a listener gets, the lexer's and the parser's.
type allErrors struct {
	*antlr.DefaultErrorListener
	msgs []string
}

func (l *allErrors) SyntaxError(_ antlr.Recognizer, _ interface{}, line, column int, msg string, _ antlr.RecognitionException) {
	l.msgs = append(l.msgs, fmt.Sprintf("%d:%d %s", line, column, msg))
}

func antlrErrors(expr string) []string {
	l := &allErrors{}
	lexer := gen.NewPlanLexer(antlr.NewInputStream(convertHanToASCII(expr)))
	lexer.RemoveErrorListeners()
	lexer.AddErrorListener(l)
	p := gen.NewPlanParser(antlr.NewCommonTokenStream(lexer, antlr.TokenDefaultChannel))
	p.RemoveErrorListeners()
	p.AddErrorListener(l)
	p.GetInterpreter().SetPredictionMode(antlr.PredictionModeLL)
	p.Expr()
	return l.msgs
}

func galopErrors(expr string) []string {
	l := &allErrors{}
	lexer := gen.NewPlanGalopLexer(antlr.NewInputStream(convertHanToASCII(expr)))
	lexer.RemoveErrorListeners()
	lexer.AddErrorListener(l)
	p := gen.NewPlanGalopParser(antlr.NewCommonTokenStream(lexer, antlr.TokenDefaultChannel))
	p.RemoveErrorListeners()
	p.AddErrorListener(l)
	p.Expr()
	return l.msgs
}

// TestGalopParserReportsANTLRErrors mutates the corpus (text inserted,
// dropped or put around a span) and requires every error, lexical and
// syntactic, in the same order.
func TestGalopParserReportsANTLRErrors(t *testing.T) {
	rnd := rand.New(rand.NewSource(1))
	junk := []string{"#", "$", "\"", "'", "@", "(", ")", "[", "]", ",", "&&", "==", "in", "not", "1", "x", "`", "?"}
	withErrors := 0
	for _, expr := range corpusList() {
		r := []rune(expr)
		for k := 0; k < 8; k++ {
			i := rnd.Intn(len(r) + 1)
			var mutant string
			switch k % 3 {
			case 0:
				mutant = string(r[:i]) + junk[rnd.Intn(len(junk))] + string(r[i:])
			case 1:
				if i == len(r) {
					continue
				}
				mutant = string(r[:i]) + string(r[i+1:])
			default:
				j := rnd.Intn(len(r) + 1)
				if j < i {
					i, j = j, i
				}
				mutant = string(r[:i]) + junk[rnd.Intn(len(junk))] + string(r[i:j]) + junk[rnd.Intn(len(junk))] + string(r[j:])
			}
			want, got := antlrErrors(mutant), galopErrors(mutant)
			if fmt.Sprint(want) != fmt.Sprint(got) {
				t.Errorf("%q:\n ANTLR %q\n galop %q", mutant, want, got)
			}
			if len(want) > 0 {
				withErrors++
			}
		}
	}
	if withErrors < 300 {
		t.Errorf("only %d mutants have errors, want at least 300", withErrors)
	}
}

// BenchmarkCorpus_Galop is BenchmarkCorpus_TwoStage's corpus parsed by galop.
func BenchmarkCorpus_Galop(b *testing.B) { benchParseSet(b, corpusList(), galopLexParse) }
